def calculate_fibonacci(n):
    """Calculates the nth Fibonacci number where F(1)=1, F(2)=1."""
    if n <= 0:
        return 0
    elif n == 1 or n == 2:
        return 1

    a, b = 1, 1
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

def is_prime(num):
    """Checks if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def sum_first_n_primes(n):
    """Calculates the sum of the first n prime numbers."""
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return sum(primes)

if __name__ == "__main__":
