    fib_25 = calculate_fibonacci(25)

    # Task 2: Sum of the first 100 prime numbers
    prime_sum_100 = sum_first_n_primes(100)

    print(f"The 25th Fibonacci number (F(25)) is: {fib_25}")
    print(f"The sum of the first 100 prime numbers is: {prime_sum_100}")
